41	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
42	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
43	    @Mapping(target = "possibleDuplicate", expression = "java(possibleDuplicate(owner))")
44	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneDisplay(owner))")
45	    OwnerDto toOwnerDto(Owner owner);
46	
47	    /** The owner's canonical API path, formatted '/api/owners/&lt;id&gt;'; absent until the owner
48	     *  has been persisted and assigned an id. */
49	    default String selfLink(Owner owner) {
50	        return owner.getId() == null ? null : "/api/owners/" + owner.getId();
51	    }
52	
53	    /** The owner's stored E.164 telephone formatted for humans; see {@link TelephoneDisplay}. */
54	    default String telephoneDisplay(Owner owner) {
55	        return TelephoneDisplay.of(owner.getTelephone());
56	    }
57	
58	    /** The owner's derived identity key: normalized telephone, email and household id joined. */
59	    default String identityKey(Owner owner) {
60	        return IdentityKey.of(owner);
61	    }
62	
63	    /** Whether the owner was flagged as a possible duplicate at registration, i.e. it carries
64	     *  the id of an existing owner it possibly duplicates. */
65	    default boolean possibleDuplicate(Owner owner) {
66	        return owner.getPossibleDuplicateOf() != null;
67	    }
68	
69	    /** The owner's salutation: the optional title prefixed to the last name, or the last name
70	     *  alone when no title is on file; see {@link Salutation}. */
71	    default String salutation(Owner owner) {
72	        return Salutation.of(owner.getTitle(), owner.getLastName());
73	    }
74	
75	    /** Format an owner's name for display as 'LastName, FirstName'. */
76	    default String displayName(Owner owner) {
77	        return owner.getLastName() + ", " + owner.getFirstName();
78	    }
79	
80	    /** The upper-cased first letters of firstName and lastName, dot-separated with a trailing dot (e.g. 'J.S.'). */
81	    default String initials(Owner owner) {
82	        return initial(owner.getFirstName()) + initial(owner.getLastName());
83	    }
84	
85	    private String initial(String name) {
86	        return name == null || name.isEmpty() ? "" : Character.toUpperCase(name.charAt(0)) + ".";
87	    }
88	
89	    /** The owner's membership number, formatted '&lt;customerCode&gt;-M&lt;YY&gt;' where YY is the
90	     *  fiscal year of the registration date (see {@link FiscalYear}, e.g. 'SPR-SMI-0007-M26').
91	     *  Absent until both the customer code and registration date have been assigned. */
92	    default String membershipNumber(Owner owner) {
93	        String customerCode = owner.getCustomerCode();
94	        LocalDate registrationDate = owner.getRegistrationDate();
95	        if (customerCode == null || registrationDate == null) {
96	            return null;
97	        }
98	        return String.format("%s-M%02d", customerCode, FiscalYear.shortYear(registrationDate));
99	    }
100	
101	    /** The owner's fiscal year, formatted 'FY&lt;YY&gt;' from the fiscal year of the
102	     *  registration date (see {@link FiscalYear}); absent until the registration date is set. */
103	    default String fiscalYear(Owner owner) {
104	        return FiscalYear.label(owner.getRegistrationDate());
105	    }
106	
107	    /** The Luhn check digit (0-9) over the digits of the owner's customerCode; absent until the
108	     *  customer code has been assigned. */
109	    default Integer checkDigit(Owner owner) {
110	        String customerCode = owner.getCustomerCode();
111	        return customerCode == null ? null : Luhn.checkDigit(customerCode);
112	    }
113	
114	    /** The owner's region, read back from the region segment of its customerCode (the identity's
115	     *  {@code <REGION>-<HASH8>} form). Until the customer code has been assigned it falls back to
116	     *  deriving the region from the postcode range first (NSW 2000-2099, VIC 3000-3099,
117	     *  QLD 4000-4099), then the city-to-region table (Sydney-&gt;NSW, Melbourne-&gt;VIC,
118	     *  Brisbane-&gt;QLD), or 'UNKNOWN' otherwise. */
119	    default String locality(Owner owner) {
120	        String region = CustomerCode.region(owner.getCustomerCode());
121	        return region != null ? region : Locality.region(owner.getCity(), owner.getPostcode());
122	    }
123	
124	    /** The owner's IANA timezone, derived from its region ('locality') via the fixed
125	     *  region-to-timezone table (NSW-&gt;Australia/Sydney, VIC-&gt;Australia/Melbourne,
126	     *  QLD-&gt;Australia/Brisbane); absent when the region has no mapped timezone. */
127	    default String timezone(Owner owner) {
128	        return Timezone.of(locality(owner));
129	    }
130	
131	    /** The owner's preferred contact channel: 'EMAIL' when an email address is on file,
132	     *  otherwise 'PHONE'. */
133	    default String contactPreference(Owner owner) {
134	        String email = owner.getEmail();
135	        return email != null && !email.isBlank() ? "EMAIL" : "PHONE";
136	    }
137	
138	    /** The owner's age band at its registration date, derived from its birth date: 'MINOR'
139	     *  (under 18), 'ADULT' (18-64) or 'SENIOR' (65+); absent until a birth date is on file. */
140	    default String ageBand(Owner owner) {
141	        return AgeBand.of(owner.getBirthDate(), owner.getRegistrationDate());
142	    }
143	
144	    Owner toOwner(OwnerDto ownerDto);
145	
146	    @Mapping(target = "id", ignore = true)
147	    @Mapping(target = "pets", ignore = true)
148	    Owner toOwner(OwnerFieldsDto ownerDto);
149	
150	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
151	
152	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
153	
154	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
155	        OwnerPageDto ownerPageDto = new OwnerPageDto();
156	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
157	        ownerPageDto.setPage(ownerPage.getNumber());
158	        ownerPageDto.setSize(ownerPage.getSize());
159	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
160	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
161	        return ownerPageDto;
162	    }
163	}
